RUNS = [0]


def make(scale, table):
    def body(x, y):
        RUNS[0] += 1
        for c in kt.par(1, on=kt.vc):
            v = kt.unpack(kt.load(x[0:4, :]))
            kt.store(y[0:4, :], v * (scale + float(table[0])))

    return kt.Kernel.build("g", body, {"x": kt.In(4, 32), "y": kt.Out(4, 32)})


def facts():
    g = {"x": TY.TensorSpec.make((4, 32))}
    a = make(2.0, (0.0,)).trace(g, machine=MACHINE)
    b = make(2.0, (0.0,)).trace(g, machine=MACHINE)
    plain_runs = RUNS[0]
    c = make(2.0, np.zeros(1)).trace(g, machine=MACHINE)
    d = make(2.0, np.zeros(1)).trace(g, machine=MACHINE)
    return {
        "plain_same": a is b,
        "plain_runs": plain_runs,
        "array_same": c is d,
        "array_runs": RUNS[0] - plain_runs,
    }
